:root {
  --accent-1: #3b82f6;
  --accent-2: #3b82f6;
  --accent-light: #3b82f6;
  --accent-bg: rgba(59,130,246,0.08);
  --bg-card: #121220;
  --text-muted: rgba(255,255,255,0.5);
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  font-family:'Inter',sans-serif;
  background:#06060c;
  color:#eeeef2;
  overflow-x:hidden;
  line-height:1.6;
}
::-webkit-scrollbar{width:6px}
::-webkit-scrollbar-track{background:#06060c}
::-webkit-scrollbar-thumb{background:rgba(255,255,255,0.1);border-radius:3px}
.container{max-width:1200px;margin:0 auto;padding:0 24px}
.gradient-accent{
  background:linear-gradient(135deg,var(--accent-1),var(--accent-2));
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  background-clip:text;
}
.gradient-bg{
  background:linear-gradient(135deg,var(--accent-1),var(--accent-2));
}
.section-tag{
  display:inline-flex;align-items:center;gap:8px;
  padding:6px 14px;border-radius:20px;font-size:12px;
  background:var(--accent-bg);color:var(--accent-light);
  border:1px solid rgba(255,255,255,0.06);
  font-weight:500;letter-spacing:0.5px;
}
.section-title{
  font-family:'Space Grotesk',sans-serif;
  font-size:clamp(1.8rem,4vw,2.8rem);
  font-weight:700;line-height:1.15;
}
.section-subtitle{
  color:var(--text-muted);
  max-width:600px;margin:0 auto 48px;
  text-align:center;font-size:0.95rem;line-height:1.7;
}
img{max-width:100%;display:block}
.btn{display:inline-flex;align-items:center;gap:10px;padding:14px 32px;border-radius:12px;
  font-size:14px;font-weight:600;text-decoration:none;cursor:pointer;
  font-family:'Space Grotesk',sans-serif;transition:all .3s;border:none;}
.btn-primary{background:linear-gradient(135deg,var(--accent-1),var(--accent-2));color:#fff;box-shadow:0 4px 20px rgba(59,130,246,0.25);}
.btn-primary:hover{transform:translateY(-2px);box-shadow:0 8px 30px rgba(59,130,246,0.35);}
.btn-secondary{background:rgba(255,255,255,0.04);color:#eeeef2;border:1px solid rgba(255,255,255,0.08);}
.btn-secondary:hover{background:rgba(255,255,255,0.08);}
.btn-whatsapp{background:#25D366;color:#fff;}
.btn-whatsapp:hover{transform:translateY(-2px);box-shadow:0 8px 25px rgba(37,211,102,0.35);}
nav{
  position:fixed;top:0;left:0;right:0;z-index:100;
  background:rgba(6,6,12,0.85);backdrop-filter:blur(20px);
  border-bottom:1px solid rgba(255,255,255,0.04);
}
nav .container{display:flex;align-items:center;justify-content:space-between;height:64px;}
.nav-logo{display:flex;align-items:center;gap:10px;text-decoration:none;color:#fff;font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:1rem;}
.nav-logo-icon{
  width:32px;height:32px;border-radius:8px;
  display:flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,var(--accent-1),var(--accent-2));
  font-size:12px;font-weight:700;color:#fff;flex-shrink:0;
}
.nav-links{display:flex;gap:24px;list-style:none;align-items:center;}
.nav-links a{font-size:13px;color:rgba(255,255,255,0.5);text-decoration:none;transition:color .3s;font-weight:500;}
.nav-links a:hover{color:#fff;}
.nav-toggle{display:none;flex-direction:column;gap:5px;cursor:pointer;background:none;border:none;padding:4px;}
.nav-toggle span{display:block;width:24px;height:2px;background:#fff;border-radius:2px;transition:all .3s;}
.hero{
  min-height:100vh;display:flex;align-items:center;
  padding-top:64px;position:relative;overflow:hidden;
  background:linear-gradient(180deg,#06060c 0%,#0c0c1a 50%,#06060c 100%);
}
.hero::before{
  content:'';position:absolute;inset:0;
  background:radial-gradient(ellipse at 30% 40%,rgba(59,130,246,0.04) 0%,transparent 60%);
  pointer-events:none;
}
.hero-content{position:relative;z-index:2;width:100%;}
.hero-grid{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center;}
.hero h1{font-family:'Space Grotesk',sans-serif;font-size:clamp(2.5rem,5vw,4rem);font-weight:700;line-height:1.1;margin:16px 0;}
.hero p{font-size:1.05rem;color:var(--text-muted);line-height:1.7;max-width:500px;margin-bottom:32px;}
.hero-actions{display:flex;flex-wrap:wrap;gap:12px;}
.hero-stats{display:flex;gap:32px;margin-top:40px;flex-wrap:wrap;}
.hero-stat-num{font-family:'Space Grotesk',sans-serif;font-size:1.8rem;font-weight:700;}
.hero-stat-label{font-size:12px;color:rgba(255,255,255,0.4);margin-top:2px;}
.hero-visual{
  border-radius:16px;overflow:hidden;
  aspect-ratio:4/3;
  background:linear-gradient(135deg,#0c0c1a,#0e0e18);
  border:1px solid rgba(255,255,255,0.06);
  display:flex;align-items:center;justify-content:center;
  flex-direction:column;
}
.hero-visual-icon{font-size:80px;opacity:0.15;}
.hero-visual-text{font-size:14px;color:rgba(255,255,255,0.2);margin-top:8px;}
.card{
  background:var(--bg-card);border:1px solid rgba(255,255,255,0.04);
  border-radius:16px;padding:28px;
  transition:all .3s;
}
.card:hover{transform:translateY(-4px);border-color:rgba(59,130,246,0.15);}
.card-icon{font-size:2rem;margin-bottom:12px;color:var(--accent-light);}
.card h3{font-family:'Space Grotesk',sans-serif;font-weight:600;font-size:1.1rem;margin-bottom:8px;}
.card p{font-size:0.85rem;color:var(--text-muted);line-height:1.6;}
.services-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:20px;}
.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start;}
.contact-item{display:flex;align-items:center;gap:16px;padding:16px;border-radius:12px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);margin-bottom:12px;text-decoration:none;color:#eeeef2;}
.contact-icon{width:44px;height:44px;border-radius:12px;display:flex;align-items:center;justify-content:center;flex-shrink:0;}
.contact-label{font-size:11px;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:1px;margin-bottom:2px;}
.contact-value{font-size:14px;font-weight:500;}
.contact-small{font-size:12px;color:rgba(255,255,255,0.35);margin-top:4px;}
.map-placeholder{
  background:linear-gradient(135deg,#0c0c1a,#0e0e18);border:1px solid rgba(255,255,255,0.06);
  border-radius:16px;min-height:300px;
  display:flex;align-items:center;justify-content:center;flex-direction:column;
}
.map-placeholder-icon{font-size:40px;color:rgba(255,255,255,0.15);margin-bottom:12px;}
.map-placeholder-text{font-size:13px;color:rgba(255,255,255,0.3);}
.map-iframe{width:100%;border:none;border-radius:16px;min-height:300px;}
.whatsapp-float{
  position:fixed;bottom:24px;right:24px;z-index:50;
  width:56px;height:56px;border-radius:50%;background:#25D366;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 4px 20px rgba(37,211,102,0.4);
  transition:all .3s;cursor:pointer;text-decoration:none;color:#fff;font-size:24px;
}
.whatsapp-float:hover{transform:scale(1.1);}
.social-links{display:flex;gap:12px;margin-top:16px;flex-wrap:wrap;}
.social-link{
  width:44px;height:44px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.06);
  color:rgba(255,255,255,0.5);font-size:18px;text-decoration:none;
  transition:all .3s;
}
.social-link:hover{background:linear-gradient(135deg,var(--accent-1),var(--accent-2));color:#fff;transform:translateY(-2px);}
footer{border-top:1px solid rgba(255,255,255,0.04);padding:48px 0;}
.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:40px;margin-bottom:32px;}
.footer-brand-desc{font-size:0.8rem;color:rgba(255,255,255,0.35);line-height:1.7;max-width:300px;margin-top:12px;}
.footer-col-title{font-size:11px;color:rgba(255,255,255,0.3);text-transform:uppercase;letter-spacing:1.5px;margin-bottom:16px;font-weight:600;}
.footer-links{list-style:none;}
.footer-links li{margin-bottom:8px;}
.footer-links a{font-size:0.85rem;color:rgba(255,255,255,0.4);text-decoration:none;transition:color .3s;}
.footer-links a:hover{color:#fff;}
.footer-bottom{border-top:1px solid rgba(255,255,255,0.04);padding-top:24px;text-align:center;font-size:12px;color:rgba(255,255,255,0.3);}
.footer-bottom a{color:var(--accent-light);text-decoration:none;}
.fade-up{opacity:0;transform:translateY(30px);transition:all .7s cubic-bezier(.4,0,.2,1);}
.fade-up.visible{opacity:1;transform:translateY(0);}
section{padding:96px 0;}
.horários-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-top:16px;}
.horário-item{background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);border-radius:10px;padding:12px 16px;text-align:center;}
.horário-dia{font-size:12px;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px;}
.horário-hora{font-size:15px;font-weight:600;font-family:'Space Grotesk',sans-serif;}
@media(max-width:768px){
  .hero-grid,.contact-grid{grid-template-columns:1fr;gap:32px;}
  .footer-grid{grid-template-columns:1fr 1fr;}
  .nav-links{display:none;position:absolute;top:100%;left:0;right:0;background:rgba(6,6,12,0.98);flex-direction:column;padding:20px 24px;gap:12px;border-bottom:1px solid rgba(255,255,255,0.04);}
  .nav-links.open{display:flex;}
  .nav-toggle{display:flex;}
  section{padding:64px 0;}
  .hero{min-height:auto;padding:120px 0 60px;}
  .hero-stats{gap:20px;}
}
@media(max-width:480px){
  .footer-grid{grid-template-columns:1fr;}
  .hero-actions{flex-direction:column;}
  .hero-actions .btn{width:100%;justify-content:center;}
}

